const STATE_KEY='angaya-crush-save-v1';
function defaults(){return {nextLevel:1,mapCursorLevel:1,coins:100,best:{},music:true,sfx:true,musicVolume:42,sfxVolume:78,tutorialSeen:false,tutorialV3Seen:false,tutorialV4Seen:false,tools:{coconut:0,fishing:0,shovel:0},careerScore:0,careerGames:0,chapterScores:Array(CHAPTERS.length).fill(0),chapterGames:Array(CHAPTERS.length).fill(0)};}
function loadState(){try{const s=JSON.parse(localStorage.getItem(STATE_KEY)||'null');if(s&&typeof s==='object')return {...defaults(),...s,mapCursorLevel:Math.max(1,Math.min(TOTAL_LEVELS,Number(s.mapCursorLevel??s.nextLevel)||1)),nextLevel:Math.max(1,Math.min(TOTAL_LEVELS+1,Number(s.nextLevel)||1)),coins:Math.max(0,Number(s.coins)||0),best:s.best&&typeof s.best==='object'?s.best:{},
 careerScore:Math.max(0,Math.floor(Number(s.careerScore)||0)),
 careerGames:Math.max(0,Math.floor(Number(s.careerGames)||0)),
 chapterScores:Array.from({length:CHAPTERS.length},(_,i)=>Math.max(0,Math.floor(Number(s.chapterScores?.[i])||0))),
 chapterGames:Array.from({length:CHAPTERS.length},(_,i)=>Math.max(0,Math.floor(Number(s.chapterGames?.[i])||0))),
 tools:{coconut:Math.max(0,Math.floor(Number(s.tools?.coconut??0)||0)),fishing:Math.max(0,Math.floor(Number(s.tools?.fishing??0)||0)),shovel:Math.max(0,Math.floor(Number(s.tools?.shovel??0)||0))}};}catch(e){}return defaults();}
let state=loadState(),page='home',game=null,toastTimer=null,moveToken=0,audioCtx=null,suppressClickUntil=0;
const $=sel=>document.querySelector(sel);
const enc=x=>encodeURIComponent(x);
function photoUrl(c){if(c.photo)return typeof OFFLINE_PHOTOS!=='undefined'&&OFFLINE_PHOTOS[c.photo]||'assets/photos/'+c.photo;const name=enc(c.file.replace(/ /g,'_'));return 'https://thumb.wikimedia.org/wikipedia/commons/thumb/'+c.hash[0]+'/'+c.hash+'/'+name+'/960px-'+name;}
function scene(c){return c.photo?`background-image:url("${photoUrl(c)}")`:`background-image:url("${photoUrl(c)}"),url("assets/${c.key}.svg")`}
function appBg(){const c=CHAPTERS[0];return `background-image:linear-gradient(180deg,rgba(14,38,50,.28),rgba(255,248,238,.15) 22%,rgba(255,248,238,.68) 72%,rgba(241,251,249,.95) 100%),url("${photoUrl(c)}");background-size:cover,cover;background-position:center,center;`}
function chapterStart(index){let x=1;for(let i=0;i<index;i++)x+=CHAPTERS[i].n;return x;}
function chapterEnd(index){return chapterStart(index)+CHAPTERS[index].n-1;}
function chapterOfLevel(level){if(level>TOTAL_LEVELS)return CHAPTERS.length-1;for(let i=0;i<CHAPTERS.length;i++){if(level<=chapterEnd(i))return i;}return CHAPTERS.length-1;}
function chapterRevealed(index){return Math.max(0,Math.min(CHAPTERS[index].n,state.nextLevel-chapterStart(index)));}
function currentChapter(){return chapterOfLevel(state.nextLevel);}
function completeCount(){return Math.min(TOTAL_LEVELS,state.nextLevel-1);}
function isFinished(){return state.nextLevel>TOTAL_LEVELS;}

function treasurePathPoints(){
 if(window.__angayaTreasurePts)return window.__angayaTreasurePts;
 const anchors=TREASURE_PATH_ANCHORS,segs=[];let total=0;
 for(let i=0;i<anchors.length-1;i++){
  const a=anchors[i],b=anchors[i+1],len=Math.hypot(b[0]-a[0],b[1]-a[1]);
  segs.push({a,b,len});total+=len;
 }
 const pts=[];
 for(let n=0;n<TOTAL_LEVELS;n++){
  const target=(n/(TOTAL_LEVELS-1))*total;let acc=0,p=segs[segs.length-1].b;
  for(const seg of segs){if(acc+seg.len>=target){const t=seg.len?((target-acc)/seg.len):0;p=[seg.a[0]+(seg.b[0]-seg.a[0])*t,seg.a[1]+(seg.b[1]-seg.a[1])*t];break;}acc+=seg.len;}
  pts.push({x:p[0],y:p[1]});
 }
 window.__angayaTreasurePts=pts;return pts;
}
function mapCursor(){
 const max=Math.min(state.nextLevel,TOTAL_LEVELS);
 return Math.max(1,Math.min(max,Math.trunc(Number(state.mapCursorLevel)||max)));
}
function knightMarker(level){
 const p=treasurePathPoints()[level-1];
 // Original vector knight, drawn as a scalable chess piece, with a blue and golden pedestal.
 const horse=`<svg class="knight-svg" viewBox="0 0 64 82" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><linearGradient id="knightGold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fffae0"/><stop offset=".4" stop-color="#e7b66e"/><stop offset="1" stop-color="#b98041"/></linearGradient><linearGradient id="knightBase" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#3878ae"/><stop offset="1" stop-color="#122f57"/></linearGradient></defs><ellipse cx="32" cy="77" rx="24" ry="4" fill="#513718" opacity=".25"/><path d="M19 63 C19 56 24 50 24 43 L11 43 Q6 40 8 35 L15 22 L19 11 L26 18 L34 8 L40 18 Q48 24 45 39 C44 49 47 55 49 63 Z" fill="url(#knightGold)" stroke="#614024" stroke-width="2.5" stroke-linejoin="round"/><path d="M11 35 L17 34 L23 37" fill="none" stroke="#83542b" stroke-width="2"/><path d="M28 22 Q37 25 39 36" fill="none" stroke="#fff7dc" stroke-width="3" opacity=".7"/><ellipse cx="25" cy="27" rx="2.8" ry="3" fill="#1b2940"/><circle cx="24" cy="26" r=".9" fill="#fff"/><path d="M13 42 Q21 46 27 41" fill="none" stroke="#71452b" stroke-width="2"/><rect x="16" y="59" width="34" height="6" rx="2.5" fill="#e1b474" stroke="#593f2a" stroke-width="2"/><path d="M13 64 H52 L56 73 H9Z" fill="url(#knightBase)" stroke="#d9ac61" stroke-width="2.2"/><rect x="7" y="72" width="50" height="7" rx="3" fill="url(#knightBase)" stroke="#ffcf79" stroke-width="2"/></svg>`;
 return `<div class="chess-knight-marker ${p.y<33?'near-top':''}" id="map-knight" style="left:${p.x}%;top:${p.y}%" role="img" aria-label="Position du cavalier : niveau ${level}"><div class="knight-bob">${horse}</div><span class="knight-level-badge" aria-hidden="true">NIVEAU ${level}</span></div>`;
}
function renderTreasurePoints(interactive=true,preview=false){
 const pts=treasurePathPoints(),selection=mapCursor();
 return pts.map((p,idx)=>{
  const level=idx+1,won=Boolean(state.best[level])||level<state.nextLevel,selected=level===selection,locked=level>state.nextLevel;
  const cls=['map-node',won?'done':'unexplored',selected?'selected':'',locked?'locked':''].filter(Boolean).join(' ');
  const disabled=locked||!interactive?'disabled':'';
  const action=interactive&&!locked?'data-action="select-map-level"':'';
  return `<button type="button" class="${cls}" style="left:${p.x}%;top:${p.y}%" ${action} ${disabled} data-level="${level}" aria-label="${won?'Niveau réussi':'Niveau à découvrir'} ${level}${selected?', position du cavalier':''}" title="${won?'Réussi':'À découvrir'} : niveau ${level}"></button>`;
 }).join('');
}
function renderTreasureMapView(){
  const maxUnlocked=Math.min(state.nextLevel,TOTAL_LEVELS);
  const selected=mapCursor(),previous=selected>1?selected-1:null,next=selected<maxUnlocked?selected+1:null;
  return `<div class="treasure-shell"><div class="map-heading"><div class="eyebrow">🗺️ CARTE DU TRÉSOR</div><h1 class="title">Route des niveaux</h1></div>
    <section class="treasure-card"><div class="treasure-map-scroll"><div class="treasure-map-board large" style="background-image:url('${TREASURE_MAP_IMAGE}')" aria-label="Carte aux points bleus réussis et aux points jaunes inexplorés">${renderTreasurePoints(true,false)}${knightMarker(selected)}</div></div><p class="map-card-tip">Déplace le cavalier avec les flèches, puis appuie sur PLAY.</p></section>
    <div class="map-legend"><span class="done"><i></i> Réussi : bleu</span><span class="locked"><i></i> Inexploré : jaune</span><span class="current"><i></i> Position du cavalier</span></div>
    <div class="level-keyboard"><button class="level-key previous" type="button" data-action="map-previous-level" ${previous===null?'disabled':''} aria-label="Déplacer le cavalier vers le niveau ${previous??'précédent indisponible'}"><span class="arrow" aria-hidden="true">❮</span><span class="key-details"><span class="key-name">PREVIOUS LEVEL</span><span class="key-number">${previous===null?'—':`N° ${previous}`}</span></span></button><button class="level-key forward" type="button" data-action="map-next-level" ${next===null?'disabled':''} aria-label="Déplacer le cavalier vers le niveau ${next??'suivant indisponible'}"><span class="key-details"><span class="key-name">NEXT LEVEL</span><span class="key-number">${next===null?'—':`N° ${next}`}</span></span><span class="arrow" aria-hidden="true">❯</span></button>
      <button type="button" class="level-key map-play-key" id="map-play-btn" data-action="map-play-selected" aria-label="Jouer le niveau ${selected}"><span class="play-arrow" aria-hidden="true">▶</span><span class="key-details"><span class="key-name">PLAY</span><span class="key-number">N° ${selected}</span></span></button></div></div>`;
}

function moveMapCursor(target){
 const max=Math.min(state.nextLevel,TOTAL_LEVELS),dest=Math.max(1,Math.min(max,Math.trunc(Number(target)||1)));
 if(dest===mapCursor()||page!=='map')return;
 const old=mapCursor();state.mapCursorLevel=dest;save();
 const p=treasurePathPoints()[dest-1],marker=document.getElementById('map-knight');
 if(marker){marker.style.left=`${p.x}%`;marker.style.top=`${p.y}%`;marker.setAttribute('aria-label',`Position du cavalier : niveau ${dest}`);}
 const oldDot=document.querySelector(`.map-node[data-level="${old}"]`),newDot=document.querySelector(`.map-node[data-level="${dest}"]`);
 oldDot?.classList.remove('selected');newDot?.classList.add('selected');
 if(oldDot)oldDot.setAttribute('aria-label',oldDot.getAttribute('aria-label').replace(', position du cavalier',''));
 if(newDot)newDot.setAttribute('aria-label',newDot.getAttribute('aria-label')+', position du cavalier');
  const badge=marker?.querySelector('.knight-level-badge');
  if(badge)badge.textContent=`NIVEAU ${dest}`;
  marker?.classList.toggle('near-top',p.y<33);
 const prev=document.querySelector('.level-key.previous'),next=document.querySelector('.level-key.forward');
 if(prev){prev.disabled=dest<=1;prev.querySelector('.key-number').textContent=dest<=1?'—':`N° ${dest-1}`;prev.setAttribute('aria-label',dest<=1?'Niveau précédent indisponible':`Déplacer le cavalier vers le niveau ${dest-1}`);}
 if(next){next.disabled=dest>=max;next.querySelector('.key-number').textContent=dest>=max?'—':`N° ${dest+1}`;next.setAttribute('aria-label',dest>=max?'Niveau suivant verrouillé':`Déplacer le cavalier vers le niveau ${dest+1}`);}
 const play=document.getElementById('map-play-btn');
  if(play){play.setAttribute('aria-label',`Jouer le niveau ${dest}`);play.querySelector('.key-number').textContent=`N° ${dest}`;}
 snd('tap');
}

function save(){try{localStorage.setItem(STATE_KEY,JSON.stringify(state));}catch(e){}}
// ANGAYA AUDIO V11.16 — « SUNSHINE DROP » pour les 160 niveaux.
// Un seul lecteur musical pour toutes les missions : la piste continue sans
// être redémarrée lorsque le joueur change de niveau ou de palier.
const SOUNDTRACKS = [
 {name:'Bande épique et enchanteresse',file:'accueil'},
 {name:'SUNSHINE DROP — Electro Pop',file:'sunshine_drop'}
];
const AUDIO_OGG_SUPPORTED = (() => {
 try { return !!new Audio().canPlayType('audio/ogg; codecs="vorbis"').replace(/no/, ''); }
 catch(e) { return false; }
})();
const EFFECTS = ['tap','swap','invalid','break_3','break_4','break_5',
 'combo_2','combo_3','combo_4','combo_5','fall','shuffle','booster',
 'hint','victory','chapter','defeat','pause','unpause', 'power_coconut','power_fishing','power_shovel',
 'arcade_ready_impact','arcade_go_impact','arcade_war_horns','arcade_war_drums','arcade_great_sparkle',
 'arcade_victory','arcade_applause','arcade_applause_short','parchment_unroll','parchment_roll'];
function soundUrl(path){return typeof EMBEDDED_AUDIO!=='undefined' && EMBEDDED_AUDIO[path] || path;}
let soundUnlocked=false, currentMusic=null, currentMusicTrack=-1, oldMusic=null;
let musicFadeTimer=null, musicDuck=1, musicDuckTimer=null, introMusicVolume=1;
const fxBuffers=Object.create(null),fxPending=Object.create(null);
function getSoundContext(){
 try{const Native=window.AudioContext||window.webkitAudioContext;
  if(!Native)return null;
  if(!audioCtx)audioCtx=new Native();
  if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});
  return audioCtx;
 }catch(e){return null;}
}
function primeEffects(){
 const ctx=getSoundContext();if(!ctx)return;
 EFFECTS.forEach(name=>{
  if(fxBuffers[name]||fxPending[name])return;
  fxPending[name]=fetch(soundUrl('audio/sfx/'+name+'.wav'))
    .then(r=>{if(!r.ok)throw Error('SFX HTTP '+r.status);return r.arrayBuffer();})
    .then(bytes=>ctx.decodeAudioData(bytes)).then(buffer=>{fxBuffers[name]=buffer;})
    .catch(()=>{});
 });
}
function fx(name,volume=1,delaySec=0){
 if(!state.sfx||document.hidden)return;
 const volumeScale=(Number(state.sfxVolume??78)/100)*volume;
 const ctx=getSoundContext(),buffer=fxBuffers[name];
 if(ctx && buffer){
  try{const source=ctx.createBufferSource(),gain=ctx.createGain();
    source.buffer=buffer;gain.gain.value=Math.min(1.25,volumeScale);
    source.connect(gain);gain.connect(ctx.destination);
    source.start(ctx.currentTime+Math.max(0,delaySec));return;
  }catch(e){}
 }
 // Secours avant décodage ou sans AudioContext : chaque bruitage a sa propre voix.
 const play=()=>{try{const node=new Audio(soundUrl('audio/sfx/'+name+'.wav'));
  node.volume=Math.min(1,volumeScale);node.play().catch(()=>{});
 }catch(e){}};
 if(delaySec>0)setTimeout(play,Math.round(delaySec*1000));else play();
}
function snd(kind='tap',details={}){
 if(kind==='match'){
  const count=details.count||3,chain=details.chain||1;
  fx(count>=5?'break_5':count>=4?'break_4':'break_3',.87);
  // Les grosses cascades sont désormais accompagnées seulement par les tambours de guerre.
  return;
 }
 const map={bad:'invalid',win:'victory',tap:'tap',loss:'defeat'};
 fx(map[kind]||kind);
}
// V11.14 — Original battle atmosphere: staged impact cues, war horns, war drums for GREAT cascades only.
// No voice, no external audio. Sounds respect mute and Effects volume settings.
const ARCADE_INSTRUMENTS={
 ready:'arcade_ready_impact',go:'arcade_go_impact',
 great:'arcade_great_sparkle',congratulations:'arcade_victory',loss:'arcade_applause_short'
};
let arcadeTimers=[],arcadeCueEpoch=0,arcadeSoundTimers=[];
const arcadeSoundNodes=new Set();
let warDrumTrack=null;
function stopWarDrums(immediate=false){
 const track=warDrumTrack;if(!track)return;warDrumTrack=null;
 if(track.source){
  try{if(!immediate&&track.ctx){const now=track.ctx.currentTime;track.gain.gain.cancelScheduledValues(now);track.gain.gain.setValueAtTime(Math.max(.001,track.gain.gain.value),now);track.gain.gain.exponentialRampToValueAtTime(.001,now+.26);track.source.stop(now+.29);}else track.source.stop();}catch(e){}
 }else if(track.audio){
  if(!immediate){track.audio.volume*=.28;setTimeout(()=>{track.audio.pause();track.audio.currentTime=0;},240);}
  else{track.audio.pause();track.audio.currentTime=0;}
 }
}
function startWarDrums(){
 if(warDrumTrack||!state.sfx||document.hidden||Number(state.sfxVolume??78)<=0)return;
 const v=Math.min(1,(Number(state.sfxVolume??78)/100)*.80);
 const ctx=getSoundContext(),buffer=fxBuffers.arcade_war_drums;
 if(ctx&&buffer){
  try{
   const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;source.loop=true;
   const now=ctx.currentTime;gain.gain.setValueAtTime(.001,now);gain.gain.exponentialRampToValueAtTime(Math.max(.002,v),now+.19);
   source.connect(gain);gain.connect(ctx.destination);source.start();warDrumTrack={ctx,source,gain};
   source.onended=()=>{if(warDrumTrack?.source===source)warDrumTrack=null;};
  }catch(e){}
 }else{
  try{const audio=new Audio(soundUrl('audio/sfx/arcade_war_drums.wav'));audio.loop=true;audio.volume=v;audio.play().catch(()=>{});warDrumTrack={audio};}catch(e){}
 }
 duckForMoment(.59,900);
}
function stopArcadeSound(){
 stopWarDrums(true);arcadeSoundTimers.forEach(clearTimeout);arcadeSoundTimers=[];
 for(const node of arcadeSoundNodes){try{if(node.stop)node.stop();else{node.pause();node.currentTime=0;}}catch(e){}}
 arcadeSoundNodes.clear();
}
function playArcadeSound(name,volume=1,delayMs=0){
 if(!state.sfx||document.hidden||Number(state.sfxVolume??78)<=0)return;
 if(delayMs){arcadeSoundTimers.push(setTimeout(()=>playArcadeSound(name,volume),delayMs));return;}
 const v=Math.max(0,Math.min(1.1,(Number(state.sfxVolume??78)/100)*volume));
 const ctx=getSoundContext(),buffer=fxBuffers[name];
 if(ctx&&buffer){
  try{const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;gain.gain.value=v;
   source.connect(gain);gain.connect(ctx.destination);arcadeSoundNodes.add(source);
   source.onended=()=>arcadeSoundNodes.delete(source);source.start();return;}catch(e){}
 }
 try{const audio=new Audio(soundUrl('audio/sfx/'+name+'.wav'));audio.preload='auto';audio.volume=Math.min(1,v);
  arcadeSoundNodes.add(audio);audio.addEventListener('ended',()=>arcadeSoundNodes.delete(audio),{once:true});
  audio.play().catch(()=>arcadeSoundNodes.delete(audio));}catch(e){}
}
function arcadeCue(key){
 // Large combos use sustained war drums, triggered and stopped by resolveCascades.
 if(key==='super_combo'||key==='fantastique')return;
 if(!state.sfx||document.hidden||Number(state.sfxVolume??78)<=0)return;
 const track=ARCADE_INSTRUMENTS[key];if(!track)return;
 if(key==='ready'){
  // The battle fanfare begins WITH READY and builds into GO (no third READY GO stage).
  duckForMoment(.45,2850);
  playArcadeSound('arcade_war_horns',.86);
  playArcadeSound('arcade_ready_impact',.71);
  return;
 }
 if(key==='go'){playArcadeSound('arcade_go_impact',.88);return;}
 if(key==='great'){playArcadeSound(track,.52);return;}
 stopArcadeSound();
 if(key==='congratulations'){
  duckForMoment(.39,4900);playArcadeSound(track,.85);playArcadeSound('arcade_applause',.75,380);
 }else if(key==='loss'){
  duckForMoment(.62,2750);playArcadeSound(track,.72,100);
 }
}
function clearArcadeBanner(){const el=document.getElementById('arcade-announcer');if(el){el.className='arcade-announcer';el.textContent='';}}
function cancelArcadeCues(){arcadeCueEpoch++;arcadeTimers.forEach(clearTimeout);arcadeTimers=[];clearArcadeBanner();stopArcadeSound();}
function showArcadeBanner(type,title,subtitle){
 const el=document.getElementById('arcade-announcer');if(!el)return;
 const text=document.createElement('strong');text.className='arcade-announce-title';
 if(type==='start'){
  const ready=document.createElement('span');ready.className='arcade-ready-word';ready.textContent='READY';
  const go=document.createElement('span');go.className='arcade-go-word';go.textContent='GO';
  text.append(ready,' ',go);text.setAttribute('aria-label','READY GO');
 }else text.textContent=title;
 const subtitleEl=document.createElement('small');subtitleEl.className='arcade-announce-subtitle';subtitleEl.textContent=subtitle;
 const card=document.createElement('div');card.className='arcade-announce-card';
 const starA=document.createElement('span');starA.className='arcade-side-star';starA.textContent='✦';starA.setAttribute('aria-hidden','true');
 const starB=starA.cloneNode(true);starB.textContent='✧';
 const veil=document.createElement('div');veil.className='arcade-veil';veil.setAttribute('aria-hidden','true');
 card.append(starA,text,subtitleEl,starB);el.replaceChildren(veil,card);
 el.className='arcade-announcer active is-'+type;
}
function beginLevelIntro(){
 if(!game||!game.introPending||page!=='game'||document.querySelector('#modal-root .modal')||!document.getElementById('arcade-announcer'))return;
 const ref=game,token=moveToken;
 cancelArcadeCues();const epoch=arcadeCueEpoch;
 ref.introPending=false;ref.introAnimating=true;ref.busy=true;
 showArcadeBanner('start','READY GO',`NIVEAU ${ref.level}`);
 const el=document.getElementById('arcade-announcer');
 // Only TWO visual stages: READY, then GO. The fanfare starts on READY;
 // its strong final brass chord arrives with GO at ~1.33 seconds.
 el?.classList.add('stage-ready');arcadeCue('ready');
 const stage=(ms,fn)=>arcadeTimers.push(setTimeout(()=>{
  if(epoch!==arcadeCueEpoch||page!=='game'||game!==ref||moveToken!==token)return;
  fn(document.getElementById('arcade-announcer'));
 },ms));
 stage(1330,el=>{if(!el)return;el.classList.remove('stage-ready');el.classList.add('stage-go');arcadeCue('go');});
 stage(3020,()=>{ref.introAnimating=false;ref.busy=false;clearArcadeBanner();});
}
// Original soft breeze + swallow call composition. Plays only during an active level.
let natureAudio=null;
function stopNatureAmbience(){if(natureAudio){natureAudio.pause();natureAudio.currentTime=0;}}
function natureAmbienceVolume(){return Math.max(0,Math.min(.14,(Number(state.sfxVolume??78)/100)*.12));}
function syncNatureAmbience(){
 const active=page==='game'&&Boolean(game)&&!game.victoryStarted&&!document.hidden&&state.sfx&&soundUnlocked&&!document.querySelector('#modal-root .modal');
 if(!active){if(natureAudio&&!natureAudio.paused)natureAudio.pause();return;}
 if(!natureAudio){
  natureAudio=new Audio(soundUrl('audio/ambience/brise_hirondelles.mp3'));
  natureAudio.preload='auto';natureAudio.loop=true;
 }
 natureAudio.volume=natureAmbienceVolume();
 if(natureAudio.paused)natureAudio.play().catch(()=>{});
}
let ambientVisualTimer=null;
function stopAmbientVisuals(){
 if(ambientVisualTimer){clearTimeout(ambientVisualTimer);ambientVisualTimer=null;}
 document.querySelectorAll('#ambient-visual-layer .ambient-visual').forEach(n=>n.remove());
}
function ambientVisualsActive(){
 return page==='game'&&Boolean(game)&&!game.victoryStarted&&!document.hidden&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.querySelector('#modal-root .modal');
}
function ambientVisualLayer(){return document.getElementById('ambient-visual-layer');}
function scheduleAmbientVisuals(initial=false){
 if(ambientVisualTimer){clearTimeout(ambientVisualTimer);ambientVisualTimer=null;}
 if(!ambientVisualsActive())return;
 const delay=initial?(33000+Math.random()*12000):(34000+Math.random()*12000);
 ambientVisualTimer=setTimeout(()=>{
  spawnAmbientVisual();
  scheduleAmbientVisuals(false);
 },delay);
}
function syncAmbientVisuals(initial=false){
 if(!ambientVisualsActive()){stopAmbientVisuals();return;}
 if(!ambientVisualLayer())return;
 scheduleAmbientVisuals(initial);
}
function spawnAmbientVisual(){
 const layer=ambientVisualLayer();
 if(!layer||!ambientVisualsActive())return;
 const roll=Math.random();
 let el;
 if(roll<.36){
  el=document.createElement('div');
  el.className='ambient-visual breeze';
  el.style.top=(10+Math.random()*62).toFixed(1)+'%';
  el.style.width=(36+Math.random()*34).toFixed(1)+'%';
  el.style.animationDuration=(5.2+Math.random()*2.4).toFixed(2)+'s';
 }else if(roll<.70){
  el=document.createElement('div');
  el.className='ambient-visual flock';
  el.style.top=(6+Math.random()*34).toFixed(1)+'%';
  el.style.left='-18%';
  el.style.animationDuration=(6.4+Math.random()*2.2).toFixed(2)+'s';
  el.innerHTML='<svg class="bird-a" viewBox="0 0 38 24"><path d="M2 12 Q10 5 19 13 Q28 3 36 9 M18 13 l-4 7 7-5"/></svg><svg class="bird-b" viewBox="0 0 38 24"><path d="M2 12 Q10 5 19 13 Q28 3 36 9 M18 13 l-4 7 7-5"/></svg>';
 }else{
  el=document.createElement('div');
  el.className='ambient-visual sunray';
  el.style.top=(-10+Math.random()*14).toFixed(1)+'%';
  el.style.right=(-16+Math.random()*10).toFixed(1)+'%';
  const size=150+Math.random()*80;
  el.style.width=size.toFixed(0)+'px';
  el.style.height=size.toFixed(0)+'px';
  el.style.animationDuration=(2.8+Math.random()*1.4).toFixed(2)+'s';
 }
 layer.appendChild(el);
 const cleanup=()=>el.remove();
 el.addEventListener('animationend',cleanup,{once:true});
 setTimeout(cleanup,9000);
}

function desiredMusicTrack(){return page==='game' && game ? 1 : 0;}
function soundtrackName(){return SOUNDTRACKS[desiredMusicTrack()].name;}
function baseMusicVolume(){return Math.min(.68,Math.max(0,(Number(state.musicVolume??42)/100)*.82))*musicDuck*introMusicVolume;}
function applyMusicVolume(){if(currentMusic)currentMusic.volume=baseMusicVolume();}
function cancelMusicFade(){if(musicFadeTimer!==null){clearInterval(musicFadeTimer);musicFadeTimer=null;}}
function stopMusic(){
 cancelMusicFade();if(currentMusic)currentMusic.pause();
 if(oldMusic){oldMusic.pause();oldMusic=null;}
}
function startMusic(){
 if(!state.music||document.hidden||!soundUnlocked){stopMusic();return;}
 const target=desiredMusicTrack();
 if(target===currentMusicTrack&&currentMusic){
   applyMusicVolume();if(currentMusic.paused)currentMusic.play().catch(()=>{});
   return;
 }
 cancelMusicFade();
 if(oldMusic){oldMusic.pause();oldMusic=null;}
 const prev=currentMusic;
 const file=SOUNDTRACKS[target].file;
 const suffix='.mp3';
 const sound=new Audio(soundUrl('audio/music/'+file+suffix));
 sound.loop=true;sound.preload='auto';sound.volume=prev?0:baseMusicVolume();
 currentMusic=sound;currentMusicTrack=target;
 sound.play().catch(()=>{});
 if(!prev)return;
 oldMusic=prev;
 const begin=Date.now(),initialVolume=prev.volume;
 musicFadeTimer=setInterval(()=>{
  const ratio=Math.min(1,(Date.now()-begin)/620);
  if(oldMusic===prev)prev.volume=Math.max(0,initialVolume*(1-ratio));
  if(currentMusic===sound)sound.volume=baseMusicVolume()*ratio;
  if(ratio>=1){clearInterval(musicFadeTimer);musicFadeTimer=null;
   prev.pause();if(oldMusic===prev)oldMusic=null;}
 },40);
}
function duckForMoment(amount=.55,duration=1400){
 musicDuck=amount;applyMusicVolume();clearTimeout(musicDuckTimer);
 musicDuckTimer=setTimeout(()=>{musicDuck=1;applyMusicVolume();},duration);
}
function unlockSound(){
 soundUnlocked=true;
 if(state.music)startMusic();
 if(state.sfx){primeEffects();}
 syncNatureAmbience();
}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1900);}
function updateHeader(){const brand=$('#home-brand-logo');if(brand)brand.hidden=page!=='home';document.querySelectorAll('#bottom-nav [data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action===page));}

// Feux d'artifice continus sur la photo finale ; aucune minuterie d'arrêt :
// seule une navigation de l'utilisateur met fin à la célébration.
let angayaFireworkState=null;
function stopAngayaFireworks(){
 const fx=angayaFireworkState;angayaFireworkState=null;
 if(!fx)return;
 cancelAnimationFrame(fx.raf);
 fx.canvas.remove();
}
function startAngayaFireworks(){
 stopAngayaFireworks();
 const root=document.getElementById('modal-root');
 if(!root||!root.querySelector('.reveal-modal'))return;
 const canvas=document.createElement('canvas');canvas.className='angaya-fireworks-canvas';canvas.setAttribute('aria-hidden','true');
 root.appendChild(canvas);
 const ctx=canvas.getContext('2d');if(!ctx)return;
 const fx={canvas,ctx,raf:0,particles:[],last:performance.now(),next:0,width:0,height:0};
 angayaFireworkState=fx;
 const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const palette=['#ffd87c','#ff9c87','#fff9dc','#75ded5','#dda0ef','#f6c779'];
 function resize(){
  fx.width=window.innerWidth;fx.height=window.innerHeight;
  const scale=Math.min(window.devicePixelRatio||1,1.6);
  canvas.width=Math.round(fx.width*scale);canvas.height=Math.round(fx.height*scale);
  ctx.setTransform(scale,0,0,scale,0,0);
 }
 resize();
 function launch(){
  const x=fx.width*(.10+Math.random()*.80);
  const y=fx.height*(.08+Math.random()*.74);
  const amount=reduced?18:36;
  const tone=palette[Math.floor(Math.random()*palette.length)];
  for(let i=0;i<amount;i++){
   const angle=(i/amount)*Math.PI*2+(Math.random()-.5)*.16;
   const speed=(reduced?1.45:1.8)+Math.random()*(reduced?1.5:2.5);
   fx.particles.push({x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,
    age:0,life:50+Math.random()*26,radius:1+Math.random()*2,color:i%5===0?'#fffbed':tone});
  }
 }
 const frame=(now)=>{
  if(angayaFireworkState!==fx)return;
  if(fx.width!==window.innerWidth||fx.height!==window.innerHeight)resize();
  const dt=Math.min(2.5,(now-fx.last)/16.67||1);fx.last=now;
  ctx.clearRect(0,0,fx.width,fx.height);
  if(now>=fx.next){launch();fx.next=now+(reduced?1350:420+Math.random()*260);}
  fx.particles=fx.particles.filter(p=>p.age<p.life);
  for(const p of fx.particles){
   p.x+=p.vx*dt;p.y+=p.vy*dt;
   p.vy+=.033*dt;p.vx*=Math.pow(.991,dt);p.vy*=Math.pow(.994,dt);p.age+=dt;
   const alpha=Math.max(0,1-p.age/p.life);
   ctx.globalAlpha=alpha*.88;ctx.fillStyle=p.color;
   ctx.beginPath();ctx.arc(p.x,p.y,p.radius*(.7+alpha*.4),0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
  fx.raf=requestAnimationFrame(frame);
 };
 launch();fx.next=performance.now()+380;
 fx.raf=requestAnimationFrame(frame);
}

let pendingExitTarget=null;
function activeUnfinishedLevel(){return page==='game'&&Boolean(game)&&!game.resultRecorded&&!game.victoryStarted;}
function confirmExitLevel(target='map'){
 if(!activeUnfinishedLevel()){setPage(target);return;}
 pendingExitTarget=target;
 game.exitPromptOpen=true;
 const score=scoreFormat(game.score);
 const held=Object.values(game.earnedTools||{}).reduce((sum,n)=>sum+Math.max(0,Number(n)||0),0);
 const detail=held?` et <strong>${held} objet${held>1?'s':''} collecté${held>1?'s':''}</strong>`:' et les objets éventuellement ramassés';
 showModal(`<div class="exit-confirm-seal" aria-hidden="true">⚠️</div><h2>Quitter la partie ?</h2><p class="exit-confirm-lead">Ton niveau n'est pas encore terminé.</p><div class="exit-confirm-warning"><strong>Attention : les gains de cette partie seront perdus.</strong><p>En quittant maintenant, tu perdras <strong>${score} point${game.score>1?'s':''}</strong>${detail}. Ils ne compteront pas dans ton score total et aucun objet gagné dans ce niveau ne sera conservé.</p></div><p class="exit-confirm-saved">Tes anciens scores restent acquis, ainsi que les objets précédents non utilisés.</p><div class="exit-confirm-actions"><button type="button" class="exit-yes" data-action="confirm-exit-level">Oui, quitter</button><button type="button" class="exit-return" data-action="cancel-exit-level">↩ Retour</button></div>`, 'exit-level-modal');
}
function confirmAbandonLevel(){
 const target=pendingExitTarget||'map';
 pendingExitTarget=null;
 // game.score et game.earnedTools ne sont pas dans la sauvegarde :
 // quitter détruit les deux, même si le joueur avait des bonus non utilisés.
 if(game){game.exitPromptOpen=false;game.earnedTools={coconut:0,fishing:0,shovel:0};}
 setPage(target,true);
}
function cancelAbandonLevel(){
 pendingExitTarget=null;
 if(game){
  game.exitPromptOpen=false;
  const pendingEnd=Boolean(game.pendingEndCheck);
  game.pendingEndCheck=false;
  closeModal();
  // La pause avait temporairement baissé la musique : un retour rétablit son volume normal.
  musicDuck=1;clearTimeout(musicDuckTimer);applyMusicVolume();
  if(pendingEnd){
   if(goalsReached(game))winLevel();
   else if(game.moves<=0)loseLevel();
   else{game.busy=false;if(!anyMove(game.board))refreshBoardWithWave();}
  }
 }else closeModal();
}
function setPage(next, confirmed=false){
 if(!confirmed&&next!=='game'&&activeUnfinishedLevel()){confirmExitLevel(next);return;}
 pendingExitTarget=null;cancelArcadeCues();cancelPowerFx();stopAngayaFireworks();stopNatureAmbience();stopAmbientVisuals();page=next;game=next==='game'?game:null;moveToken++;musicDuck=1;clearTimeout(musicDuckTimer);$('#modal-root').innerHTML='';render();startMusic();syncNatureAmbience();syncAmbientVisuals(true);window.scrollTo(0,0);
}
function showModal(html,extraClass=''){if(game?.introAnimating){game.introPending=true;game.busy=true;cancelArcadeCues();}else if(extraClass!=='reveal-modal')stopArcadeSound();stopAngayaFireworks();stopNatureAmbience();stopAmbientVisuals();$('#modal-root').innerHTML=`<div class="modal ${extraClass}" role="dialog" aria-modal="true">${html}</div>`;}
function closeModal(){stopAngayaFireworks();const paused=Boolean(document.querySelector('.modal [data-action=close-modal]')&&document.querySelector('.modal h2')?.textContent==='Pause 😎');$('#modal-root').innerHTML='';if(paused){musicDuck=1;clearTimeout(musicDuckTimer);applyMusicVolume();snd('unpause');}syncNatureAmbience();syncAmbientVisuals(true);if(game?.introPending)setTimeout(beginLevelIntro,35);}
function puzzleHtml(c,index,opts={}){
 const revealed=opts.revealed===undefined?chapterRevealed(index):opts.revealed;
 const newest=opts.newest===undefined?-1:opts.newest;
 return `<div class="${opts.small?'puzzle-thumbnail':'puzzle-area'} ${opts.celebrate?'photo-complete':''}" aria-label="Puzzle ${revealed} cases révélées sur ${c.n}"><div class="puzzle-photo ${c.portrait?'portrait-photo':''}" style='${scene(c)}'></div><div class="puzzle-grid" style="grid-template-columns:repeat(${c.cols},1fr);grid-template-rows:repeat(${c.rows},1fr)">${Array.from({length:c.n},(_,i)=>`<div class="puzzle-cell ${i<revealed?'revealed':'hidden'} ${i===newest?'new':''}">${i<revealed?'':'✦'}</div>`).join('')}</div></div>`;
}

function angayaAdsChoice(){
 try{return localStorage.getItem(window.ANGAYA_ADS_KEY)||'';}catch(_e){return '';}
}
function angayaAdsChoiceCard(){
 if(angayaAdsChoice())return '';
 return `<section class="angaya-ads-choice" aria-label="Préférences publicitaires"><strong>📢 Publicités partenaires</strong><p>Des annonces Monetag peuvent contribuer à financer Angaya Crush. Elles ne sont activées qu'après ton accord. <a href="../confidentialite.html" target="_blank" rel="noopener noreferrer">Confidentialité</a>.</p><div class="angaya-ads-choice-actions"><button type="button" class="agree" data-action="ads-accept">Accepter</button><button type="button" class="decline" data-action="ads-refuse">Refuser</button></div></section>`;
}
function angayaAdsSettingsCard(){
 const choice=angayaAdsChoice();
 const label=choice==='yes'?'Autorisées':choice==='no'?'Refusées':'Non défini';
 return `<div class="wide-card angaya-ads-settings"><div class="section-title" style="margin:0 0 6px">📢 Publicités CVMemoire</div><span class="angaya-ads-state">Monetag · ${label}</span><p>Les annonces In-Page Push de CVMemoire sont facultatives. Le fournisseur choisit leur contenu et leur fréquence. <a href="../confidentialite.html" target="_blank" rel="noopener noreferrer">Politique de confidentialité</a>.</p><div class="angaya-ads-choice-actions"><button type="button" class="agree" data-action="ads-accept">Accepter les annonces</button><button type="button" class="decline" data-action="ads-refuse">Refuser les annonces</button></div></div>`;
}
function setAngayaAdsChoice(accept){
 const next=accept?'yes':'no';
 const previous=angayaAdsChoice();
 try{localStorage.setItem(window.ANGAYA_ADS_KEY,next);}catch(_e){toast('Impossible de mémoriser la préférence publicitaire.');return;}
 // Un script publicitaire déjà chargé ne peut pas être complètement retiré :
 // recharger pour prendre en compte un refus, sans perdre la progression sauvegardée.
 if(!accept&&previous==='yes'&&document.getElementById('angaya-monetag-zone-11802765')){
  location.reload();return;
 }
 if(accept&&window.loadAngayaSiteAds)window.loadAngayaSiteAds();
 render();
 toast(accept?'Publicités partenaires autorisées.':'Publicités partenaires refusées.');
}
